public final class WindowMotion {
 public static final long FRESH=150_000_000L;
 public record Packet(long frame,long input,long generation,long time,boolean open,WindowMotionGeometry.Progressed geometry,CollisionShape shape){}
 public static final class Entry {
  final WeakReference<IsoWindow> source;final WeakReference<IsoGridSquare> square;final Object recipe;final ArrayList<Part> parts=new ArrayList<>();final WindowMotionCapture.Pair pair;final boolean suppressed;final long epoch;final float rise;boolean target,invalid;double from,progress;long changed;Packet packet;
  Entry(IsoWindow w,Object recipe,Object op,WindowMotionCapture.Pair pair,boolean suppressed,long epoch,float rise,TileMesh original,TileMesh replacement,Entry before){source=new WeakReference<>(w);square=new WeakReference<>(w.getSquare());this.recipe=recipe;this.pair=pair;this.suppressed=suppressed;this.epoch=epoch;this.rise=rise;parts.add(new Part(this,op,original,replacement));target=w.IsOpen();progress=before==null?(target?1:0):before.progress;from=progress;changed=System.nanoTime();}
  public IsoWindow source(){return source.get();}public IsoGridSquare square(){return square.get();}public WindowMotionCapture.Pair pair(){return pair;}public boolean suppressed(){return suppressed;}
 }
 private static final class Part {final Entry entry;final Object op;final TileMesh original,replacement;volatile int first=-1,count;Part(Entry entry,Object op,TileMesh original,TileMesh replacement){this.entry=entry;this.op=op;this.original=original;this.replacement=replacement;}}
 private static final class Scope {final IsoGridSquare square;final Object recipe;final float x,y,z;final long epoch;IsoWindow candidate;IsoSprite sprite;boolean failed;final ArrayList<Entry> emitted=new ArrayList<>();Scope(IsoGridSquare square,Object recipe,float x,float y,float z){this.square=square;this.recipe=recipe;this.x=x;this.y=y;this.z=z;epoch=WindowMotion.epoch;}}
 private static final ThreadLocal<ArrayDeque<Scope>> scopes=new ThreadLocal<>();private static final ThreadLocal<Integer> overflow=new ThreadLocal<>();private static final WeakHashMap<IsoWindow,Entry> entries=new WeakHashMap<>();private static final WeakHashMap<Object,Part> ops=new WeakHashMap<>();private static final Set<IsoGridSquare> dirty=Collections.newSetFromMap(new WeakHashMap<>());private static final WindowMotionCapture capture=new WindowMotionCapture();private static final Object demand=new Object();
 private static volatile boolean enabled;private static volatile long epoch;private static Field recipeField,opMesh,opOwner,opKind,cookerFloats;private static Constructor<TileMesh> meshConstructor;private static volatile String detail="Window motion Off";
 public static boolean enabled(){return enabled;}public static long epoch(){return epoch;}
 public static void configure(boolean value){if(value&&(!NativeOwnerVisibility.request(demand,true)||!AuthoredDepth.request(demand,true))){value=false;NativeOwnerVisibility.request(demand,false);AuthoredDepth.request(demand,false);}List<IsoGridSquare> restore; synchronized(WindowMotion.class){enabled=value;epoch++;restore=entries.values().stream().filter(e->e.suppressed).map(Entry::square).filter(Objects::nonNull).distinct().toList();entries.clear();ops.clear();dirty.addAll(restore);detail=value?"Window motion waiting for original measured pairs and both eye outputs":"Window motion Off";}WindowMotionRenderHook.rejectScope();WorldRigCapture.requestWindowMotion(value);NativeOwnerVisibility.request(demand,value);AuthoredDepth.request(demand,value);tick();}
 public static String status(){return detail+"; "+WindowMotionRenderHook.status();}
 static boolean focused(){var input=Engine.latestInput;var actor=player();return enabled&&Main.ready()&&Engine.active()&&Engine.worldPresent&&input!=null&&input.focused()&&actor!=null&&!actor.isDead()&&actor.getCell()!=null&&actor.getSquare()!=null&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server;}
 static boolean eligible(){return focused()&&Engine.eyeRendering();}
 private static IsoPlayer player(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 private static Field field(Class<?> type,String name)throws ReflectiveOperationException{var value=type.getDeclaredField(name);value.setAccessible(true);return value;}
 private static void access()throws ReflectiveOperationException{if(recipeField!=null)return;recipeField=field(WorldMesher.class,"recipe");var op=Class.forName("viewpoint.world.Recipe$Op",false,WindowMotion.class.getClassLoader());opMesh=field(op,"mesh");opOwner=field(op,"owner");opKind=field(op,"kind");var cooker=Class.forName("viewpoint.world.Cook$Cooker",false,WindowMotion.class.getClassLoader());cookerFloats=field(cooker,"n");meshConstructor=TileMesh.class.getDeclaredConstructor(float[].class);meshConstructor.setAccessible(true);}
 public static boolean begin(IsoGridSquare square,float x,float y,float z){
  var stack=scopes.get();if(!enabled&&stack==null)return false;if(stack==null){stack=new ArrayDeque<>();scopes.set(stack);}if(stack.size()>=8){Integer n=overflow.get();overflow.set(n==null?1:n+1);for(var s:stack){s.candidate=null;s.failed=true;}return true;}
  Object recipe=null;try{if(enabled&&Main.ready()&&square!=null){access();recipe=recipeField.get(null);}}catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){detail="Window recipe contract unavailable";}
  stack.addLast(new Scope(square,recipe,x,y,z));return true;
 }
 public static void candidate(IsoGridSquare square,IsoObject object,IsoSprite sprite,boolean skipped){var stack=scopes.get();var s=stack==null?null:stack.peekLast();if(s==null)return;s.candidate=null;s.sprite=null;if(overflow.get()!=null||skipped||!enabled||s.epoch!=epoch||s.recipe==null||s.failed||square!=s.square||object==null||object.getClass()!=IsoWindow.class||object.getSquare()!=square||object.getSprite()!=sprite||WindowMotionProfile.forSprite(sprite==null?null:sprite.name)==null)return;s.candidate=(IsoWindow)object;s.sprite=sprite;}
 public static void clearCandidate(){var stack=scopes.get();var s=stack==null?null:stack.peekLast();if(s!=null){s.candidate=null;s.sprite=null;}}
 public static void emitted(Object op,TileMesh winner,Texture texture,float x,float y,float z,int kind){
  var stack=scopes.get();var s=stack==null?null:stack.peekLast();if(s==null||s.candidate==null||overflow.get()!=null||!enabled||s.epoch!=epoch||s.emitted.size()>=8||op==null||winner==null||texture==null||kind<0||kind>2||s.failed)return;var window=s.candidate;
  try{access();float rise=WorldMesher.rise(window);int owner=(((s.square.getX()&7)+(s.square.getY()&7)*8)<<2)|(window.getNorth()?1:2);if(recipeField.get(null)!=s.recipe||window.getSprite()!=s.sprite||window.getSquare()!=s.square||window.getObjectIndex()<0||opMesh.get(op)!=winner||opOwner.getInt(op)!=owner||opKind.getInt(op)!=kind||Math.abs(x-s.x)>.0001f||Math.abs(y-s.y)>.0001f||Math.abs(z-s.z-rise)>.0001f||!Float.isFinite(rise)||Math.abs(rise)>.5f)return;
   Entry active=null;for(var e:s.emitted)if(e.source()==window){active=e;break;}
   if(active!=null&&active.parts.size()>=8){s.failed=true;return;}var pair=active==null?capture.prepare(window,winner):active.pair;if(pair==null||texture!=(window.IsOpen()?pair.openArt().texture():pair.closedArt().texture())||!Arrays.equals(winner.data,(window.IsOpen()?pair.open():pair.closed()).data().mesh()))return;
   boolean replace=active==null?WindowMotionRenderHook.warmed(window,pair):active.suppressed;TileMesh copied=null;if(replace){var parts=WindowMotionGeometry.split(pair.profile(),window.IsOpen()?pair.open().data():pair.closed().data());copied=meshConstructor.newInstance((Object)WindowMotionGeometry.outer(pair.profile(),parts));if(copied.vertCount==0)return;opMesh.set(op,copied);}
   if(active==null){Entry before;synchronized(WindowMotion.class){before=entries.get(window);}active=new Entry(window,s.recipe,op,pair,replace,epoch,rise,winner,copied,before);s.emitted.add(active);NativeOwnerVisibility.watchRecipe(s.recipe,s.square);}else{if(active.parts.size()>=8){s.failed=true;return;}active.parts.add(new Part(active,op,winner,copied));}

  }catch(Exception|LinkageError unavailable){detail="Window original pair or region proof rejected";}
 }
 public static void end(boolean success){Integer depth=overflow.get();if(depth!=null){if(depth<=1)overflow.remove();else overflow.set(depth-1);return;}var stack=scopes.get();if(stack==null)return;var s=stack.pollLast();if(stack.isEmpty())scopes.remove();if(s==null)return;s.candidate=null;
  synchronized(WindowMotion.class){for(var entry:s.emitted){var source=entry.source();if(!success||s.failed||!enabled||s.epoch!=epoch||source==null||!capture.current(entry.pair,source)){try{if(entry.suppressed)for(var part:entry.parts)opMesh.set(part.op,part.original);}catch(ReflectiveOperationException|RuntimeException ignored){}continue;}if(entries.size()>=32&&!entries.containsKey(source)){try{if(entry.suppressed)for(var part:entry.parts)opMesh.set(part.op,part.original);}catch(ReflectiveOperationException|RuntimeException ignored){}continue;}var old=entries.put(source,entry);if(old!=null)for(var part:old.parts)ops.remove(part.op);for(var part:entry.parts)ops.put(part.op,part);}}
 }
 public static int cookBegin(Object cooker,Object op){synchronized(WindowMotion.class){if(!ops.containsKey(op))return -1;}try{access();int n=cookerFloats.getInt(cooker);return n>=0&&n%14==0?n/14:-1;}catch(ReflectiveOperationException|RuntimeException unavailable){return -1;}}
 public static void cookEnd(Object cooker,Object op,int first,boolean success){synchronized(WindowMotion.class){var part=ops.get(op);if(part==null)return;try{int n=cookerFloats.getInt(cooker);int count=n/14-first;var expected=part.entry.suppressed?part.replacement:part.original;if(!success||first<0||n<0||n%14!=0||count<0||count%3!=0||count>expected.vertCount||opMesh.get(op)!=expected){part.first=-1;part.entry.invalid=true;return;}part.first=first;part.count=count;}catch(ReflectiveOperationException|RuntimeException unavailable){part.first=-1;part.entry.invalid=true;}}}
 static boolean current(Entry entry){var w=entry==null?null:entry.source();return enabled&&entry!=null&&!entry.invalid&&entry.epoch==epoch&&w!=null&&w.getSquare()==entry.square()&&!entry.parts.isEmpty()&&entry.parts.stream().allMatch(p->p.first>=0)&&entry.parts.stream().anyMatch(p->p.count>0)&&WorldMesher.rise(w)==entry.rise&&capture.current(entry.pair,w);}
 static synchronized List<Entry> entries(){return entries.values().stream().filter(WindowMotion::current).toList();}
 static synchronized List<Entry> tracked(){return List.copyOf(entries.values());}
 static boolean visible(Entry entry,SceneData scene){if(!current(entry))return false;var data=NativeOwnerVisibility.committed(entry.recipe,entry.square());if(data==null)return false;for(var part:entry.parts)if(part.count>0&&!NativeOwnerVisibility.surface(scene,data,entry.square(),entry.pair.profile().north()?1:2,part.first,part.count))return false;return true;}
 static synchronized Packet packet(Entry entry,WorldRigFrame rig,long frame,long now){if(!current(entry)||rig==null)return null;if(entry.packet!=null&&entry.packet.frame==frame)return entry.packet.generation()==rig.generation()&&entry.packet.input()==rig.inputTime()&&entry.packet.open()==entry.source().IsOpen()?entry.packet:null;var w=entry.source();boolean target=w.IsOpen();if(target!=entry.target){entry.from=entry.progress;entry.target=target;entry.changed=now;}double goal=target?1:0,weight=Math.min(1,Math.max(0,(now-entry.changed)/240_000_000d));entry.progress=entry.from+(goal-entry.from)*weight;var g=WindowMotionGeometry.progress(entry.pair.profile(),entry.pair.pieces(),entry.progress,false,false,false);g=WindowMotionGeometry.endpoint(entry.pair.profile(),g,entry.pair.closed().data(),entry.pair.open().data());var shape=NativeWindowGeometry.window(g.contacts(),g.glass().length>0);entry.packet=new Packet(frame,rig.inputTime(),rig.generation(),now,target,g,shape);return entry.packet;}
 public static Packet publication(IsoWindow window){if(window==null||window.isSmashed()||window.isGlassRemoved()||window.isDestroyed())return null;return WindowMotionRenderHook.publication(window);}
 static synchronized void redraw(Entry entry){if(entry!=null&&entry.square()!=null)dirty.add(entry.square());}
 static synchronized void restore(Entry entry){if(entry==null||!entry.suppressed||entries.get(entry.source())!=entry)return;entry.invalid=true;redraw(entry);}
 static synchronized void reject(){for(var e:entries.values())restore(e);}
 public static void tick(){if(enabled&&!focused())WindowMotionRenderHook.rejectScope();List<IsoGridSquare> work; synchronized(WindowMotion.class){work=new ArrayList<>(dirty);dirty.clear();var it=entries.values().iterator();while(it.hasNext()){var e=it.next();if(!enabled||e.invalid||e.epoch!=epoch||e.source()==null||e.square()==null||!capture.current(e.pair,e.source())){if(e.suppressed&&e.square()!=null)work.add(e.square());for(var part:e.parts)ops.remove(part.op);it.remove();}}}for(var square:work)try{square.invalidateRenderChunkLevel(256L);}catch(RuntimeException|LinkageError unavailable){detail="Window static restoration pending native invalidation";}}
 private WindowMotion(){}
}
